// Per-ayah (EveryAyah) reciters, shared by quran-listen and listening-wird
// (generated by scripts/convert-quran-listen.mjs).
import fs from "node:fs/promises";
import path from "node:path";
import { cache } from "react";

export type AyahReciter = { id: string; name: string; nameEn: string };

export const getAyahReciters = cache(async (): Promise<AyahReciter[]> =>
  JSON.parse(await fs.readFile(path.join(process.cwd(), "data/quran-listen/reciters.json"), "utf8")),
);

